package ua.aia2.guard;
import java.util.*;import net.minecraft.world.item.ItemStack;import net.minecraft.world.item.crafting.Recipe;import net.minecraft.world.level.block.entity.BlockEntity;import net.minecraft.server.level.ServerPlayer;
public class Aia2MachineGuard{
 public static final GuardPolicy BLOCKS=new GuardPolicy(),ITEMS=new GuardPolicy(),RECIPES=new GuardPolicy();public static boolean ready=true;
 public static final Map<Recipe<?>,String> live=new IdentityHashMap<>();
 public static boolean isReady(){return ready;}public static String getOwner(BlockEntity be){return be.owner;}
 public static boolean mayTick(BlockEntity be){return ready&&BLOCKS.mayTick("ad_astra:nasa_workbench",be.owner);}
 public static boolean mayProcessRecipe(BlockEntity be,Recipe<?> r){return mayTick(be)&&live.containsKey(r)&&RECIPES.mayTick(live.get(r),be.owner);}
 public static boolean mayProduce(BlockEntity be,ItemStack output){return mayTick(be)&&ITEMS.mayTick(output.getItem().id(),be.owner);}
 public static String synchronizedPlayerTeam(ServerPlayer p){return ready&&p.team.equals(p.synced)?p.team:"";}
 public static void configure(){BLOCKS.clear();ITEMS.clear();RECIPES.clear();ready=true;live.clear();BLOCKS.setRules(Map.of("ad_astra:nasa_workbench",37));ITEMS.setRules(Map.of("ad_astra:tier_1_rocket",37,"ad_astra:tier_3_rocket",38,"kubejs:aia2_tech_key_37",37,"example:registered_key",37));RECIPES.setRules(Map.of("ad_astra:t1",37,"ad_astra:t3",38));for(var p:List.of(BLOCKS,ITEMS,RECIPES)){p.setTeamProgress("team",36);p.setReady();}}
 public static void progress(int completed){for(var p:List.of(BLOCKS,ITEMS,RECIPES))p.setTeamProgress("team",completed);}
}

