package earth.terrarium.adastra.common.blockentities.machines;
import net.minecraft.world.level.block.entity.BlockEntity;import net.minecraft.world.Container;import net.minecraft.world.Containers;import net.minecraft.world.item.ItemStack;import net.minecraft.world.item.crafting.*;import net.minecraft.world.level.Level;import earth.terrarium.adastra.common.recipes.machines.NasaWorkbenchRecipe;import ua.aia2.guard.mixin.AdAstraNasaHarness;
public class NasaWorkbenchBlockEntity extends BlockEntity implements Container {
 protected NasaWorkbenchRecipe recipe;public final ItemStack[] items=new ItemStack[15];public int particles,writes,size=15;
 public NasaWorkbenchBlockEntity(){for(int i=0;i<15;i++)items[i]=ItemStack.EMPTY;}
 public void recipe(NasaWorkbenchRecipe recipe){this.recipe=recipe;}
 public int getContainerSize(){return size;}public ItemStack getItem(int slot){return items[slot];}public void setItem(int slot,ItemStack value){items[slot]=value;writes++;}
 public Level level(){return level;}
 public void spawnResultParticles(){particles++;}
 public boolean canCraft(){boolean nativeResult=recipe!=null&&recipe.matches(new RecipeInput(){public int size(){return 15;}public ItemStack getItem(int slot){return items[slot];}},level);return AdAstraNasaHarness.select(this,nativeResult);}
 public void craft(){
        if (!AdAstraNasaHarness.finish(this)) return;
        if (recipe == null) return;
        spawnResultParticles();
        Containers.dropItemStack(level(),
            getBlockPos().getX(),
            getBlockPos().getY() + 1,
            getBlockPos().getZ(),
            getItem(14).copy());

        setItem(14, ItemStack.EMPTY);
        for (int i = 0; i < 14; i++) {
            getItem(i).shrink(1);
        }
        recipe = null;
 }
}

